113	$wp_rocket_requirement_checks = new WP_Rocket_Requirements_Check(
114		[
115			'plugin_name'         => 'WP Rocket',
116			'plugin_file'         => WP_ROCKET_FILE,
117			'plugin_version'      => WP_ROCKET_VERSION,
118			'plugin_last_version' => WP_ROCKET_LASTVERSION,
119			'wp_version'          => WP_ROCKET_WP_VERSION,
120			'php_version'         => WP_ROCKET_PHP_VERSION,
121		]
122	);
123	
124	if ( $wp_rocket_requirement_checks->check() ) {
125		require WP_ROCKET_INC_PATH . 'main.php';
126	}
127	
128	unset( $wp_rocket_requirement_checks );
