178			$subscribers = [];
179	
180			if ( is_admin() ) {
181				$subscribers = $this->init_admin_subscribers();
182			} elseif ( $this->is_valid_key ) {
183				$subscribers = $this->init_valid_key_subscribers();
184			}
185	
186			return array_merge( $subscribers, $this->init_common_subscribers() );
187		}
