30		protected function handleSetting( $key, $value, $set = true ) {
31			$func     = $set ? 'add_filter' : 'remove_filter';
32			$callback = $value === 0 ? 'return_false' : 'return_true';
33	
34			switch ( $key ) {
35				case 'minify_concatenate_css':
36					$func( 'pre_get_rocket_option_minify_concatenate_css', [ $this, $callback ] );
37					break;
38	
39				case 'minify_concatenate_js':
40					$func( 'pre_get_rocket_option_minify_concatenate_js', [ $this, $callback ] );
41					break;
42	
43				case 'cdn':
44					$func( 'pre_get_rocket_option_cdn', [ $this, $callback ] );
45					break;
46	
47				case 'cdn_cnames':
48					$this->cnames = $value;
49					$func( 'pre_get_rocket_option_cdn_cnames', [ $this, 'set_cnames' ] );
50					break;
51	
52				case 'cdn_zone':
53					$this->zones = $value;
54					$func( 'pre_get_rocket_option_cdn_zone', [ $this, 'set_zones' ] );
55			}
56		}
