70		protected function assertFilesExists( $files ) {
71			foreach ( $files as $file ) {
72				if ( $this->skipGzCheck( $file ) ) {
73					continue;
74				}
75	
76				$this->assertTrue( $this->filesystem->exists( $file ) );
77			}
